parameters.jsCode:
// Parse the uploaded CSV, find the phone/name/tags columns, normalize numbers to
// international digits (E.164 without '+'), drop invalid and duplicate rows.
const MAX_ROWS = 5000;
const form = $input.first();
const list = String(form.json.list_name || '').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
if (!list) throw new Error('List name is required (letters, numbers, dashes).');
const cc = String(form.json.country_code || '91').replace(/\D/g, '') || '91';

const bin = form.binary || {};
const key = bin.contacts ? 'contacts' : Object.keys(bin)[0];
if (!key) throw new Error('No file received. Upload a .csv file.');
const text = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf-8').replace(/^﻿/, '');

// Small RFC4180-style parser (quotes, escaped quotes, , or ; delimiter, CRLF).
const firstLine = text.split(/\r?\n/, 1)[0] || '';
const delim = (firstLine.match(/;/g) || []).length > (firstLine.match(/,/g) || []).length ? ';' : ',';
const rows = []; let row = [], cell = '', q = false;
for (let i = 0; i < text.length; i++) {
  const c = text[i];
  if (q) { if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; continue; }
  if (c === '"') q = true;
  else if (c === delim) { row.push(cell); cell = ''; }
  else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
  else cell += c;
}
if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
const data = rows.filter(r => r.some(v => String(v).trim() !== ''));
if (data.length < 2) throw new Error('The CSV needs a header row and at least one contact.');

const header = data[0].map(h => String(h).trim().toLowerCase());
const find = names => header.findIndex(h => names.some(n => h === n || h.includes(n)));
const iPhone = find(['phone', 'mobile', 'whatsapp', 'number', 'contact no', 'cell']);
const iName = find(['name', 'full name', 'first name', 'customer']);
const iTags = find(['tag', 'label', 'group', 'segment']);
if (iPhone < 0) throw new Error(`No phone column found. Headers seen: ${header.join(', ')}. Name one column "phone".`);

const normalize = raw => {
  let s = String(raw || '').trim();
  const plus = s.startsWith('+');
  let d = s.replace(/\D/g, '');
  if (!d) return null;
  if (!plus && d.startsWith('00')) d = d.slice(2);
  else if (!plus && d.length === 11 && d.startsWith('0')) d = cc + d.slice(1);
  else if (!plus && d.length === 10) d = cc + d;
  return d.length >= 10 && d.length <= 15 ? d : null;
};

const seen = new Set(); const out = [];
let invalid = 0, dupes = 0, overLimit = 0; const invalidSamples = [];
for (const r of data.slice(1)) {
  if (out.length >= MAX_ROWS) { overLimit++; continue; }
  const phone = normalize(r[iPhone]);
  if (!phone) { invalid++; if (invalidSamples.length < 10) invalidSamples.push(String(r[iPhone] || '(blank)')); continue; }
  if (seen.has(phone)) { dupes++; continue; }
  seen.add(phone);
  const extra = {};
  header.forEach((h, idx) => { if (![iPhone, iName, iTags].includes(idx) && h) extra[h] = String(r[idx] ?? '').trim(); });
  out.push({ json: {
    key: `${list}:${phone}`, list, phone,
    name: iName >= 0 ? String(r[iName] || '').trim() : '',
    tags: iTags >= 0 ? String(r[iTags] || '').trim() : '',
    extra: JSON.stringify(extra),
  }, pairedItem: { item: 0 } });
}
if (!out.length) throw new Error(`No valid phone numbers found (${invalid} invalid, ${dupes} duplicates). Examples: ${invalidSamples.join(', ')}`);
const stats = { list, total: data.length - 1, valid: out.length, invalid, dupes, overLimit, invalidSamples };
out[0].json._stats = stats;
return out;

// Pair each WhatsApp check result with its parsed contact (same order, same count).
const parsed = $('Parse & Clean Contacts').all();
const checks = $input.all();
const now = new Date().toISOString();
return checks.map((c, i) => {
  const p = parsed[i].json;
  const ok = c.json.statusCode === 200;
  const body = c.json.body || {};
  return { json: {
    key: p.key, list: p.list, phone: p.phone, name: p.name, tags: p.tags, extra: p.extra,
    on_whatsapp: ok ? body.exists === true : false,
    whatsapp_id: ok && body.whatsappId ? body.whatsappId : '',
    check_status: ok ? (body.exists ? 'on_whatsapp' : 'not_on_whatsapp') : `check_failed_${c.json.statusCode || 'error'}`,
    opted_in: true,
    source: 'csv_upload',
    updated_at: now,
  }, pairedItem: { item: i } };
});

const saved = $('Combine Check Results').all().map(i => i.json);
const s = $('Parse & Clean Contacts').first().json._stats;
const on = saved.filter(r => r.on_whatsapp).length;
const failed = saved.filter(r => r.check_status.startsWith('check_failed')).length;
return [{ json: { ...s, saved: saved.length, onWhatsapp: on, notOnWhatsapp: saved.length - on - failed, checkFailed: failed } }];

